const price = Number(input.price_usd);
if (!isFinite(price) || price <= 0) {
  throw new Error('price_usd must be a positive number');
}
const ZERO_DECIMAL = new Set(['JPY','KRW','VND','ISK','CLP','PYG','UGX','COP','HUF','TWD','BHD','IQD','JOD','KWD','LYD','OMR','TND','RSD','MGA','RWF','XAF','XOF','XPF','BIF','CLF','DJF','GNF','KMF','MRO','VUV','WST','SLL','INR']);
const raw = Array.isArray(input.target_currencies) ? input.target_currencies : [];
const seen = new Set();
const currencies = [];
const invalid_codes = [];
for (const c of raw) {
  if (typeof c !== 'string') { invalid_codes.push(String(c)); continue; }
  const code = c.trim().toUpperCase();
  if (!/^[A-Z]{3}$/.test(code)) { invalid_codes.push(code); continue; }
  if (!seen.has(code)) { seen.add(code); currencies.push(code); }
}
let style = input.rounding_style;
if (style !== 'charm' && style !== 'prestige') style = 'auto';
const zero_decimal = currencies.filter(c => ZERO_DECIMAL.has(c));
return { price_usd: price, currencies, rounding_style: style, invalid_codes, zero_decimal };

const price = nodes.validate_inputs.output.price_usd;
const style = nodes.validate_inputs.output.rounding_style;
const zeroDecimal = new Set(nodes.validate_inputs.output.zero_decimal || []);
const results = nodes.fetch_rates.output.results || [];
const items = nodes.validate_inputs.output.currencies || [];
const price_table = [];
const skipped = [];
let first_rate_timestamp = '';
for (let i = 0; i < items.length; i++) {
  const code = items[i];
  const r = results[i];
  const rate = r && typeof r.rate === 'number' ? r.rate : null;
  if (!rate || rate <= 0) {
    skipped.push({ currency_code: code, reason: 'live rate unavailable' });
    continue;
  }
  const raw = price * rate;
  const isZero = zeroDecimal.has(code);
  let rounded, note;
  const cap = raw * 1.05;
  if (style === 'prestige') {
    if (isZero) {
      let cand = Math.ceil(raw);
      if (cand > cap) cand = Math.round(raw);
      rounded = cand;
      note = 'Prestige rounding: rounded up to a clean whole-number price within 5% tolerance.';
    } else {
      const endings = [0.00, 0.95, 0.50];
      let chosen = null;
      for (const base of [Math.ceil(raw), Math.ceil(raw) - 1]) {
        for (const e of endings) {
          const cand = Math.round((base + e) * 100) / 100;
          if (cand >= raw && cand <= cap) { chosen = cand; break; }
        }
        if (chosen !== null) break;
      }
      if (chosen === null) {
        chosen = Math.round(raw * 100) / 100;
        note = 'No clean prestige ending fit within 5% tolerance; rounded to nearest conventional price.';
      } else {
        note = 'Prestige rounding: clean .' + String(Math.round((chosen % 1) * 100)).padStart(2, '0') + ' ending within 5% tolerance.';
      }
      rounded = chosen;
    }
  } else {
    if (isZero) {
      const endings = [9, 8, 0];
      let chosen = null;
      for (const e of endings) {
        const cand = Math.floor(raw / 10) * 10 + e;
        if (cand <= cap && cand > 0) { chosen = cand; break; }
      }
      if (chosen === null) chosen = Math.round(raw);
      rounded = chosen;
      note = 'Zero-decimal currency: whole-number charm ending (' + (chosen % 10) + ') within 5% tolerance.';
    } else {
      const endings = [0.99, 0.95, 0.49, 0.00];
      let chosen = null;
      for (const e of endings) {
        const cand = Math.floor(raw) + e;
        if (cand <= cap && cand > 0) { chosen = cand; break; }
      }
      if (chosen === null) {
        chosen = Math.round(raw * 100) / 100;
        note = 'No charm ending fit within 5% tolerance; rounded to nearest conventional price.';
      } else {
        note = 'Charm ending .' + String(Math.round((chosen % 1) * 100)).padStart(2, '0') + ' chosen within 5% tolerance.';
      }
      rounded = Math.round(chosen * 100) / 100;
    }
  }
  const ts = (r && (r.date || r.timestamp)) || '';
  if (!first_rate_timestamp && ts) first_rate_timestamp = ts;
  price_table.push({
    currency_code: code,
    exchange_rate_used: rate,
    rate_timestamp: ts,
    raw_converted_price: Math.round(raw * 100) / 100,
    rounded_price: rounded,
    rounding_note: note
  });
}
return { price_table, skipped, first_rate_timestamp };

